/*
 * A165674  Triangle generated by the asymptotic expansions of the E(x,m=2,n).
 * https://oeis.org/A165674
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   a(n) = flattened triangle a(r,m) defined by * a(n,1) =
 *            n·a(n‑1,1) + (n‑1)!, * a(n,n) = 1, * a(n,m) = (n–m+1)·a(n‑1,m) +
 *            a(n‑1,m‑1) (2 ≤ m ≤ n‑1). * This function returns the OEIS
 *            sequence A165674
 * Range:     u8 n <= 10, u16 n <= 28, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* static state kept between calls */
static seq_t *cache     = NULL;        /* flattened sequence values          */
static size_t cache_len = 0;           /* number of values stored           */
static size_t cache_cap = 0;           /* allocated size of cache array      */

static idx_t  cur_row   = 0;           /* number of rows already computed   */
static seq_t *prev_row  = NULL;        /* previous row's values             */
static size_t prev_len  = 0;           /* length of prev_row                */
static seq_t  fact_prev = 1;           /* (cur_row)!  (after each row)      */

/* ensure cache has room for at least need more elements */
static void ensure_cache_capacity(size_t need)
{
    if (cache_len + need <= cache_cap) return;
    size_t new_cap = cache_cap ? (cache_cap << 1) : 16;
    while (new_cap < cache_len + need) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) abort(); /* out of memory */
    cache     = tmp;
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;                     /* below offset - behaviour undefined */
    if (n > (idx_t)SIZE_MAX) return 0;        /* too large for array index */

    /* compute rows until we have at least n values */
    while (cache_len < (size_t)n) {
        idx_t   r      = cur_row + 1;           /* next row number (1‑based) */
        size_t  r_len  = (size_t)r;             /* length of this row         */
        seq_t * row    = (seq_t *)malloc(r_len * sizeof(seq_t));
        if (!row) abort();                      /* out of memory */

        if (r == 1) {
            row[0] = 1;                         /* a(1,1) */
        } else {
            /* a(r,1) = r * a(r‑1,1) + (r‑1)! */
            row[0] = r * prev_row[0] + fact_prev;

            /* a(r,m) for 2 ≤ m ≤ r‑1 */
            for (idx_t m = 2; m <= r - 1; ++m) {
                /* m‑1 is index in 0‑based array */
                row[m - 1] = ( (r - m + 1) * prev_row[m - 1] )
                           + prev_row[m - 2];
            }
            /* a(r,r) = 1 */
            row[r - 1] = 1;
        }

        /* append the new row to the cache */
        ensure_cache_capacity(r_len);
        memcpy(cache + cache_len, row, r_len * sizeof(seq_t));
        cache_len += r_len;

        /* clean up previous row and set current as previous */
        if (prev_row) free(prev_row);
        prev_row = row;
        prev_len = r_len;

        /* update factorial of r: fact_prev becomes r! */
        fact_prev = fact_prev * r;
        cur_row   = r;
    }

    return cache[n - 1];
}
